'use strict';
function overfitGap(trainScore, valScore) {
  return trainScore - valScore;
}
function suggestLambda(gap) {
  if (gap > 0.2) return 0.1;
  if (gap > 0.1) return 0.01;
  return 0.001;
}
module.exports = { overfitGap, suggestLambda };

'use strict';
function screenSample(sample, bounds) {
  return Object.keys(bounds).every((key) => {
    const v = sample[key];
    return typeof v === 'number' && v >= bounds[key][0] && v <= bounds[key][1];
  });
}
module.exports = { screenSample };

'use strict';
function hasLeakage(trainIds, testIds) {
  const train = new Set(trainIds);
  return testIds.some((id) => train.has(id));
}
function overlapCount(trainIds, testIds) {
  const train = new Set(trainIds);
  return testIds.filter((id) => train.has(id)).length;
}
module.exports = { hasLeakage, overlapCount };

'use strict';
function recordPrediction(stats, latencyMs, confidence) {
  stats.count = (stats.count || 0) + 1;
  stats.totalLatency = (stats.totalLatency || 0) + latencyMs;
  stats.lowConfidence = (stats.lowConfidence || 0) + (confidence < 0.5 ? 1 : 0);
  return stats;
}
function avgLatency(stats) {
  return stats.count ? stats.totalLatency / stats.count : 0;
}
module.exports = { recordPrediction, avgLatency };

'use strict';
function groupCounts(samples, attr) {
  const counts = {};
  for (const s of samples) counts[s[attr]] = (counts[s[attr]] || 0) + 1;
  return counts;
}
function imbalanceRatio(counts) {
  const vals = Object.values(counts);
  if (!vals.length) return 0;
  return Math.max(...vals) / Math.min(...vals);
}
module.exports = { groupCounts, imbalanceRatio };
